{"code": "import glob
import os

# Delete the corrupted/original files (the small 133-byte ones)
for split in ['train', 'val', 'test']:
    files = glob.glob(f'data/tfrecords-jpeg-192x192/{split}/*.tfrec')
    for f in files:
        if os.path.getsize(f) < 10000:  # Less than 10KB means it's the corrupted one
            os.remove(f)
            print(f"Deleted {f}")

print("\nRemaining files:")
for split in ['train', 'val', 'test']:
    files = sorted(glob.glob(f'data/tfrecords-jpeg-192x192/{split}/*.tfrec'))
    print(f"{split}: {len(files)} files")
    if files:
        print(f"  Example: {files[0]} ({os.path.getsize(files[0])} bytes)")"}

